}

for (let n = 1; n <= 10; n++) {
  if (n % 2 === 0) continue;  // skip even numbers
  if (n > 7) break;           // stop entirely after 7
  console.log(n);
}
console.log("done");

for (let row = 1; row <= 3; row++) {
  let line = "";
  for (let col = 1; col <= 3; col++) {
    line += row * col + " ";
  }
  console.log(line.trim());
}
